//
// Blender 5.2.2 `primitive_*_add` storage-order oracle for the box, plane, grid, circle, cylinder and
// cone primitives (`tests/fixtures/primitive_uvs/primitive_uv_oracle.json`, generated by
// `generate_primitive_uv_oracle.py`). Vertices, edges and faces are compared in storage order.

use std::error::Error;

use glam::DVec3;
use potter_core::geom::{
    BoxParams, CircleFillType, CircleParams, ConeParams, CylinderParams, EndFillType, GridParams,
    IcosphereParams, Mesh, PlaneParams, TorusParams,
};
use serde_json::Value;

type TestResult = Result<(), Box<dyn Error>>;

const ORACLE: &str = include_str!("fixtures/primitive_uvs/primitive_uv_oracle.json");
const POSITION_TOLERANCE: f64 = 1.0e-5;

/// Storage order: positions, and edge and face references as indices into the vertex list.
#[derive(Debug, PartialEq)]
struct Stored {
    vertices: Vec<[f64; 3]>,
    edges: Vec<[usize; 2]>,
    faces: Vec<Vec<usize>>,
}

fn stored(mesh: &Mesh) -> Result<Stored, Box<dyn Error>> {
    let index = |id: u32| -> Result<usize, Box<dyn Error>> {
        mesh.vertices
            .iter()
            .position(|vertex| vertex.id == id)
            .ok_or_else(|| "vertex ID has no storage index".into())
    };
    let mut edges = Vec::with_capacity(mesh.edges.len());
    for edge in &mesh.edges {
        edges.push([index(edge.vertices[0])?, index(edge.vertices[1])?]);
    }
    let mut faces = Vec::with_capacity(mesh.faces.len());
    for face in &mesh.faces {
        let mut corners = Vec::with_capacity(face.vertices.len());
        for &id in &face.vertices {
            corners.push(index(id)?);
        }
        faces.push(corners);
    }
    Ok(Stored {
        vertices: mesh
            .vertices
            .iter()
            .map(|vertex| vertex.co.to_array())
            .collect(),
        edges,
        faces,
    })
}

fn expected(case: &Value) -> Result<Stored, Box<dyn Error>> {
    let mut vertices = Vec::new();
    for point in case["vertices"].as_array().ok_or("vertices missing")? {
        let coordinates = point.as_array().ok_or("position must be an array")?;
        let mut position = [0.0; 3];
        for (axis, value) in position.iter_mut().zip(coordinates) {
            *axis = value.as_f64().ok_or("coordinate must be a number")?;
        }
        vertices.push(position);
    }
    let indices = |value: &Value| -> Result<Vec<usize>, Box<dyn Error>> {
        let mut result = Vec::new();
        for item in value.as_array().ok_or("indices must be an array")? {
            result.push(usize::try_from(
                item.as_u64().ok_or("index must be an integer")?,
            )?);
        }
        Ok(result)
    };
    let mut edges = Vec::new();
    for edge in case["edges"].as_array().ok_or("edges missing")? {
        let endpoints = indices(edge)?;
        if endpoints.len() != 2 {
            return Err("edge must have two endpoints".into());
        }
        edges.push([endpoints[0], endpoints[1]]);
    }
    let mut faces = Vec::new();
    for face in case["faces"].as_array().ok_or("faces missing")? {
        faces.push(indices(face)?);
    }
    Ok(Stored {
        vertices,
        edges,
        faces,
    })
}

fn assert_matches(name: &str, mesh: &Mesh, cases: &Value) -> TestResult {
    let expected = expected(&cases[name])?;
    let actual = stored(mesh)?;
    assert_eq!(
        actual.vertices.len(),
        expected.vertices.len(),
        "{name} vertex count"
    );
    for (index, (left, right)) in actual.vertices.iter().zip(&expected.vertices).enumerate() {
        let error = (0..3)
            .map(|axis| (left[axis] - right[axis]).abs())
            .fold(0.0_f64, f64::max);
        assert!(
            error <= POSITION_TOLERANCE,
            "{name} vertex {index} is {left:?}, Blender has {right:?}"
        );
    }
    assert_eq!(actual.edges, expected.edges, "{name} edge order");
    assert_eq!(actual.faces, expected.faces, "{name} face and loop order");
    Ok(())
}

fn oracle() -> Result<Value, Box<dyn Error>> {
    let root: Value = serde_json::from_str(ORACLE)?;
    assert_eq!(root["blender_version"], "5.2.2");
    Ok(root["cases"].clone())
}

#[test]
fn box_plane_and_grid_storage_order_matches_blender() -> TestResult {
    let cases = oracle()?;
    let box_mesh = Mesh::box_mesh(BoxParams {
        size: DVec3::splat(2.0),
    })?;
    assert_matches("box_size_2", &box_mesh, &cases)?;
    let plane = Mesh::plane(PlaneParams { size: 2.0 })?;
    assert_matches("plane_size_2", &plane, &cases)?;
    let grid = Mesh::grid(GridParams {
        size_x: 2.0,
        size_y: 2.0,
        x_subdivisions: 3,
        y_subdivisions: 3,
    })?;
    assert_matches("grid_2x2", &grid, &cases)
}

#[test]
fn circle_storage_order_matches_blender() -> TestResult {
    let cases = oracle()?;
    let open = Mesh::circle(CircleParams {
        vertices: 8,
        radius: 1.0,
        fill_type: CircleFillType::Nothing,
    })?;
    assert_matches("circle_8", &open, &cases)?;
    let ngon = Mesh::circle(CircleParams {
        vertices: 5,
        radius: 0.75,
        fill_type: CircleFillType::Ngon,
    })?;
    assert_matches("circle_ngon_5", &ngon, &cases)?;
    let fan = Mesh::circle(CircleParams {
        vertices: 5,
        radius: 0.75,
        fill_type: CircleFillType::TriFan,
    })?;
    assert_matches("circle_trifan_5", &fan, &cases)
}

#[test]
fn cylinder_storage_order_matches_blender() -> TestResult {
    let cases = oracle()?;
    let cylinder = |vertices, end_fill_type| {
        Mesh::cylinder(CylinderParams {
            vertices,
            radius: 1.0,
            depth: 2.0,
            end_fill_type,
        })
    };
    assert_matches("cylinder_8", &cylinder(8, EndFillType::Ngon)?, &cases)?;
    assert_matches(
        "cylinder_default",
        &cylinder(32, EndFillType::Ngon)?,
        &cases,
    )?;
    assert_matches(
        "cylinder_8_trifan",
        &cylinder(8, EndFillType::TriFan)?,
        &cases,
    )?;
    assert_matches(
        "cylinder_8_nothing",
        &cylinder(8, EndFillType::Nothing)?,
        &cases,
    )?;
    assert_matches("cylinder_4_ngon", &cylinder(4, EndFillType::Ngon)?, &cases)
}

#[test]
fn cone_storage_order_matches_blender() -> TestResult {
    let cases = oracle()?;
    let cone = |vertices, radius1, radius2, end_fill_type| {
        Mesh::cone(ConeParams {
            vertices,
            radius1,
            radius2,
            depth: 2.0,
            end_fill_type,
        })
    };
    assert_matches("cone_8", &cone(8, 1.0, 0.0, EndFillType::Ngon)?, &cases)?;
    assert_matches(
        "cone_default",
        &cone(32, 1.0, 0.0, EndFillType::Ngon)?,
        &cases,
    )?;
    assert_matches(
        "cone_8_trifan",
        &cone(8, 1.0, 0.0, EndFillType::TriFan)?,
        &cases,
    )?;
    assert_matches(
        "cone_8_nothing",
        &cone(8, 1.0, 0.0, EndFillType::Nothing)?,
        &cases,
    )?;
    assert_matches(
        "cone_trunc_8",
        &cone(8, 1.0, 0.5, EndFillType::Ngon)?,
        &cases,
    )?;
    assert_matches(
        "cone_inverted_8",
        &cone(8, 0.0, 1.0, EndFillType::Ngon)?,
        &cases,
    )?;
    assert_matches(
        "cone_inverted_32",
        &cone(32, 0.0, 1.0, EndFillType::Ngon)?,
        &cases,
    )?;
    assert_matches(
        "cone_trunc_4_ngon",
        &cone(4, 1.0, 0.5, EndFillType::Ngon)?,
        &cases,
    )?;
    // A zero bottom radius collapses the bottom ring to its first vertex; the fan and open-end
    // variants keep that apex in its own place (there is no N-gon cap to dissolve).
    assert_matches(
        "cone_inverted_8_trifan",
        &cone(8, 0.0, 1.0, EndFillType::TriFan)?,
        &cases,
    )?;
    assert_matches(
        "cone_inverted_8_nothing",
        &cone(8, 0.0, 1.0, EndFillType::Nothing)?,
        &cases,
    )
}

#[test]
fn torus_storage_order_matches_blender() -> TestResult {
    let cases = oracle()?;
    let torus = |major_segments, minor_segments| {
        Mesh::torus(TorusParams {
            major_segments,
            minor_segments,
            major_radius: 1.0,
            minor_radius: 0.25,
            ..TorusParams::default()
        })
    };
    assert_matches("torus_8x4", &torus(8, 4)?, &cases)?;
    assert_matches("torus_default", &torus(48, 12)?, &cases)
}

#[test]
fn icosphere_storage_order_matches_blender() -> TestResult {
    let cases = oracle()?;
    for (name, subdivisions) in [
        ("ico_sphere_1", 1),
        ("ico_sphere_default", 2),
        ("ico_sphere_3", 3),
        ("ico_sphere_4", 4),
    ] {
        let icosphere = Mesh::icosphere(IcosphereParams {
            subdivisions,
            radius: 1.0,
        })?;
        assert_matches(name, &icosphere, &cases)?;
    }
    Ok(())
}

/// Blender's torus at 1152 faces, built with one edge hash map (`--threads 1`, see
/// `generate_torus_single_map_oracle.py`). Above 1000 faces Blender's edge order follows its thread
/// count, so this is the case the single-map rule is checked against.
#[test]
fn torus_single_map_edge_order_matches_blender() -> TestResult {
    const SINGLE_MAP: &str = include_str!("fixtures/primitive_uvs/torus_single_map_oracle.json");
    let root: Value = serde_json::from_str(SINGLE_MAP)?;
    assert_eq!(root["blender_version"], "5.2.2");
    let cases = root["cases"].clone();
    let torus = Mesh::torus(TorusParams {
        major_segments: 48,
        minor_segments: 24,
        major_radius: 1.0,
        minor_radius: 0.25,
        ..TorusParams::default()
    })?;
    assert_matches("torus_48x24_single_map", &torus, &cases)
}
